/* Example: basic flex container and styled boxes */
.container {
    display: flex;
    gap: 20px;
    padding: 20px;
}
.box {
    width: 100px;
    height: 100px;
    background-color: lightblue;
    border-radius: 8px;
}

/* Example of using min() for width */
.box {
    width: min(200px, 75%);
}

/* Example: limiting width with min() */
.box {
    width: min(90vw, 600px);
}

/* Example of using max() for padding */
.box {
    padding: max(10px, 3%);
}

/* Similar: responsive heading with max() */
h2 {
    font-size: max(1rem, 3vw);
}

/* Example: responsive container using clamp() */
.container {
    width: clamp(200px, 50vw, 800px);
}
